import assert from 'node:assert/strict';
import {mkdtemp,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import path from 'node:path';
const directory=await mkdtemp(path.join(tmpdir(),'crew-shutdown-'));
process.env.CREW_DATA_DIR=directory;
const {startServer}=await import('./acceptance-runtime.mjs');
let server;
try{
  server=await startServer();
  const response=await fetch(server.url+'/api/v1/health',{signal:AbortSignal.timeout(5000)});
  assert.equal((await response.json()).ok,true);
  await server.stop();
  server=null;
  console.log(JSON.stringify({ok:true,checks:['real server readiness','HTTP health','bounded SIGTERM clean exit']}));
}finally{
  if(server)await server.stop();
  await rm(directory,{recursive:true,force:true});
}
